let __v_202 = pyrt::literals::decode("{\"$tuple\":[\"That is rarer than people think, and worth saying out loud once: 'I noticed you always say thank you, and it makes a difference.' People hear the complaint version far more often than the good one.\",\"It is worth naming to their face rather than just enjoying: 'you always notice, and I appreciate it.' A thank-you that goes unmentioned tends to stop, because nobody can tell it landed.\",\"Say it back in the same plain way, in the moment: 'I appreciate that you always think to say it.' One sentence is the whole of what it takes.\"]}")?;
frame.store("GOOD_HABIT_APPRECIATED", __v_202.clone())?;
let __v_203 = pyrt::literals::decode("{\"$tuple\":[\"That is a good habit to be on the receiving end of, and worth naming to their face: 'I noticed you always think to ask me.' People rarely hear the good version of a habit, and it is usually never said.\",\"Say yes, and say why once: 'I like that you always think to include me.' The person who keeps asking is usually the one who never gets told that it lands.\",\"Enjoy it and say so in the moment rather than leaving it as a thing you only notice - 'I noticed, and I'm glad of it.' It costs nothing and it usually lands better than people expect.\"]}")?;
