let __v_210 = pyrt::literals::decode("{\"$tuple\":[\"Agree the time out loud, then say what happens if it slips: 'if you're not here by seven I'll start without you.' A consequence you actually keep is what changes a habit; being annoyed on the night does not.\",\"Say it once, without the sarcasm, in the calmest voice you have: 'when you're late it means I am waiting, and I'd rather we set a time we both mean.' Then stop being the person who waits quietly.\",\"Ask for a message rather than for punctuality, because it is the waiting that costs you: 'if you'll be more than ten minutes, text me.' That is easy to say yes to, and it gets you the thing you actually wanted.\"]}")?;
