let __v_211 = pyrt::literals::decode("{\"$tuple\":[\"Ask what they want from the conversation: 'when you bring it up, is there something you want me to say?' Somebody who goes over the same ground is usually after an answer they have not had yet, and naming that ends it quicker than changing the subject.\",\"Say where the line is once, in a warm voice: 'I've said all I can about that one - I'd rather talk about something else tonight.' Then steer, gently, to something you both enjoy.\"]}")?;
