let __v_249 = pyrt::literals::decode("{\"$tuple\":[\"Then it is a pattern rather than a bad week, and worth naming as one: 'this happens most days' lands differently from 'you did it again'. Ask for the smallest version of it - one thing, one place - because a whole list is easy to refuse and one thing is not.\",\"Each time it happens, say the same short line and nothing else. It feels repetitive to you because you are the one saying it; being boring about it is exactly what makes it stick.\"]}")?;
