let __v_250 = pyrt::literals::decode("{\"$tuple\":[\"It is not you being sensitive: a small thing that happens every day is a different thing from a small thing that happens once. Being worn down by the repetition is the honest response to it, and it is worth saying as its own sentence.\",\"You are not asking for much - you are asking for the same small thing twice - so it is worth one clear go before you decide anything. If nothing changes after you have said it plainly, that is information about them rather than about you.\",\"A thing can be small and still wear you down when it lands every day. Say the one sentence you would say to a friend in the same spot, and take your own side in it.\"]}")?;
